function minimumXORSum(nums1, nums2) {
  const n = nums1.length;
  const full = 1 << n;
  const dp = new Array(full).fill(Infinity);
  const used = new Array(full).fill(0);
  dp[0] = 0;

  for (let mask = 1; mask < full; mask++) {
    used[mask] = used[mask >> 1] + (mask & 1);
    const i = used[mask] - 1;
    for (let j = 0; j < n; j++) {
      if (mask & (1 << j)) {
        const cost = dp[mask ^ (1 << j)] + (nums1[i] ^ nums2[j]);
        dp[mask] = Math.min(dp[mask], cost);
      }
    }
  }
  return dp[full - 1];
}

