function minimumXORSum(nums1, nums2) {
  const n = nums1.length;
  const taken = new Array(n).fill(false);
  let best = Infinity;
  const place = (index, total) => {
    if (index === n) { best = Math.min(best, total); return; }
    for (let k = 0; k < n; k++) {
      if (taken[k]) continue;
      taken[k] = true;
      place(index + 1, total + (nums1[index] ^ nums2[k]));
      taken[k] = false;
    }
  };
  place(0, 0);
  return best;
}

