function generate(rand, size) {
  const n = size === 'large' ? 12 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 7);
  const kind = Math.floor(rand() * 3);
  const top = kind === 0 ? 16 : kind === 1 ? 1024 : 10000001;
  const pick = () => Math.floor(rand() * top);
  const nums1 = Array.from({ length: n }, pick);
  const nums2 = Array.from({ length: n }, pick);
  if (rand() < 0.25) {
    // Sometimes nums2 is a shuffled near-copy of nums1, so small sums are possible.
    for (let i = 0; i < n; i++) nums2[i] = rand() < 0.7 ? nums1[i] : pick();
    for (let i = n - 1; i > 0; i--) { const k = Math.floor(rand() * (i + 1)); [nums2[i], nums2[k]] = [nums2[k], nums2[i]]; }
  }
  return [nums1, nums2];
}
